        return sum(boxes[L:R + 1])

    for query in queries:
        if query[0] == 1:
            L, R, A, B = query[1], query[2], query[3], query[4]
            update_boxes(L, R, A, B)
        elif query[0] == 2:
            L, R = query[1], query[2]
            results.append(get_total_stones(L, R))

    return results

